<section id="login" class="login card"><p class="ey">JOOZZ STUDIO</p><h1>Welcome back</h1><p class="muted">Sign in to manage your website.</p><form id="loginForm"><label>Username<input name="username" required autocomplete="username"></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><p id="err" class="error"></p><button class="btn">Sign in</button></form></section>
<main id="app" class="layout hide"><aside class="side"><div class="brand">Joozz Studio</div><nav class="nav"><button data-v="dashboard" class="active">Dashboard</button><button data-v="settings">Site settings</button><button data-v="home">Home page</button><button data-v="services">Services</button><button data-v="portfolio">Portfolio</button><button data-v="about">About page</button><button data-v="contact">Contact & FAQs</button><button data-v="enquiries">Enquiries</button><button data-v="media">Media library</button><button data-v="seo">Navigation & SEO</button></nav><div class="side-status"><span>Website connected</span>Changes publish after saving</div><button id="logout" class="btn ghost">Sign out</button></aside><section class="work"><div class="head"><div><p class="ey">JOOZZ CONTENT ATELIER</p><h1 id="title">Dashboard</h1><p id="sub" class="muted">Your studio website at a glance.</p></div><div id="actions" class="actions"></div></div><div id="view"></div></section></main><div id="toast" class="toast hide"></div>
<script>
const API=<?=json_encode($api)?>,$=s=>document.querySelector(s);let csrf='',current='dashboard',items=[];const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(p,o={}){let h={'X-CSRF-Token':csrf,...o.headers};if(!(o.body instanceof FormData))h['Content-Type']='application/json';let r=await fetch(API+p,{credentials:'include',...o,headers:h}),b=await r.json().catch(()=>({}));if(!r.ok)throw Error(b.error?.message||'Something went wrong.');return b.data}function toast(t){$('#toast').textContent=t;$('#toast').classList.remove('hide');setTimeout(()=>$('#toast').classList.add('hide'),3000)}const meta={dashboard:['Dashboard','Your studio website at a glance.'],settings:['Site settings','Your brand, contact details and footer.'],home:['Home page','Edit the first impression visitors see.'],services:['Services','Add, hide or manage studio services.'],portfolio:['Portfolio','Showcase selected work.'],about:['About page','Tell your studio story.'],contact:['Contact & FAQs','Contact details and helpful answers.'],enquiries:['Enquiries','Project enquiries in one place.'],media:['Media library','Upload and reuse images and videos.'],seo:['Navigation & SEO','Website menu and search appearance.']};function nav(v){current=v;document.querySelectorAll('[data-v]').forEach(x=>x.classList.toggle('active',x.dataset.v===v));render()}document.querySelectorAll('[data-v]').forEach(x=>x.onclick=()=>nav(x.dataset.v));
async function render(){let m=meta[current];$('#title').textContent=m[0];$('#sub').textContent=m[1];$('#actions').innerHTML='';try{if(current==='dashboard')return dash();if(['services','portfolio'].includes(current))return list(current);if(current==='contact')return contactManager();if(current==='media')return media();if(current==='enquiries')return enquiries();if(current==='seo')return seo();return pageForm(current)}catch(e){$('#view').innerHTML='<div class="card error">'+esc(e.message)+'</div>'}}
async function contactManager(){await list('faqs');$('#actions').insertAdjacentHTML('afterbegin','<button class="btn ghost" onclick="pageForm(\'contact\')">Edit contact details</button>')}
async function dash(){let d=await api('/admin/dashboard');$('#view').innerHTML=`<section class="card dashboard-hero"><div><span class="live-mark">Website live</span><h2>Your creative work,<br><em style="color:var(--gold2)">beautifully managed.</em></h2><p class="muted">Everything your visitors see can be curated from this private studio workspace.</p></div></section><div class="grid"><div class="card metric"><strong>${d.newEnquiries}</strong>New enquiries</div><div class="card metric"><strong>${d.publishedPortfolioItems}</strong>Portfolio projects</div><div class="card metric"><strong>${d.publishedServices}</strong>Live services</div><div class="card metric"><strong>${d.publishedServices+d.publishedPortfolioItems}</strong>Published content</div></div><div class="card" style="margin-top:18px"><p class="ey">SHORTCUTS</p><h2>What would you like to update?</h2><p class="muted">Jump straight into the most-used areas of your website.</p><div class="actions" style="margin-top:20px"><button class="btn" onclick="edit('portfolio')">＋ Add portfolio project</button><button class="btn ghost" onclick="edit('services')">＋ Add service</button><button class="btn ghost" onclick="nav('enquiries')">View enquiries</button><button class="btn ghost" onclick="nav('home')">Edit home page</button></div></div>`}
async function list(k){let r=await api('/admin/content/'+k);items=r.items;$('#actions').innerHTML='<button class="btn" onclick="edit(\''+k+'\')">Add '+(k==='services'?'service':k==='portfolio'?'project':'FAQ')+'</button>';$('#view').innerHTML='<div class="list">'+(items.map(i=>`<div class="row"><img class="thumb" src="${esc(i.image||i.thumbnail||'')}" onerror="this.style.display='none'"><div class="grow"><b>${esc(i.title||i.question)}</b><small>${esc(i.client||i.slug||i.answer||'')}</small></div><span class="pill">${esc(i.status||((i.visible===false)?'Hidden':'Live'))}</span><button class="btn ghost" onclick="edit('${k}',${i.id})">Edit</button><button class="btn ghost danger" onclick="del('${k}',${i.id})">Delete</button></div>`).join('')||'<div class="card muted">Nothing here yet.</div>')+'</div>'}
const input=(l,n,v='',area=false)=>`<label>${l}${area?'<textarea':'<input'} name="${n}" value="${area?'':esc(v)}">${area?esc(v)+'</textarea>':''}</label>`;async function edit(k,id){let i=id?items.find(x=>x.id===id):{status:'published',visible:true,year:new Date().getFullYear()};let cats=[];if(k==='portfolio')cats=(await api('/admin/content/categories')).items;let fields=k==='services'?input('Service name','title',i.title)+input('Short introduction','tagline',i.tagline||'')+input('Description','description',i.description||'',true)+input('Image link','image',i.image||'')+input('Ideal customer','idealFor',i.idealFor||'',true):k==='portfolio'?input('Project title','title',i.title)+`<label>Category<select name="categoryId">${cats.map(c=>'<option value="'+c.id+'" '+(c.name===i.category?'selected':'')+'>'+esc(c.name)+'</option>').join('')}</select></label>`+input('Client','client',i.client||'')+input('Year','year',i.year||'')+input('Description','description',i.description||'',true)+input('Thumbnail image link','thumbnail',i.thumbnail||'')+input('Video or image link','mediaUrl',i.mediaUrl||''):input('Question','question',i.question||'')+input('Answer','answer',i.answer||'',true);$('#view').innerHTML=`<form id="form" class="card form"><h2>${id?'Edit':'Add'} ${k==='faqs'?'FAQ':k.slice(0,-1)}</h2><div class="cols">${fields}</div>${k==='portfolio'?'<label class="check"><input type="checkbox" name="featured" '+(i.featured?'checked':'')+'> Feature this project</label>':''}<label class="check"><input type="checkbox" name="hidden" ${(i.status==='hidden'||i.visible===false)?'checked':''}> Hide from website</label><div class="actions"><button class="btn">Save changes</button><button type="button" class="btn ghost" onclick="list('${k}')">Cancel</button></div></form>`;$('#form').onsubmit=async e=>{e.preventDefault();let f=e.target,d=Object.fromEntries(new FormData(f));d.status=f.hidden.checked?'hidden':'published';d.visible=!f.hidden.checked;d.featured=f.featured?.checked;try{await api('/admin/content/'+k+(id?'/'+id:''),{method:id?'PUT':'POST',body:JSON.stringify(d)});toast('Saved — your website is up to date.');list(k)}catch(e){toast(e.message)}}}async function del(k,id){if(confirm('Delete this item permanently?')){await api('/admin/content/'+k+'/'+id,{method:'DELETE'});toast('Deleted.');list(k)}}
const editorSection=(number,title,note,body)=>`<section class="card editor-section"><div class="section-head"><span class="section-no">${number}</span><div><h2>${title}</h2><p>${note}</p></div></div><div class="cols">${body}</div></section>`;
const mediaField=(label,name,value='')=>`<div class="media-control"><label>${label}<input name="${name}" value="${esc(value)}" placeholder="Paste a link or choose from your library"><small class="field-note">Use an uploaded file or a full image/video link.</small></label><button class="btn ghost" type="button" onclick="openMediaPicker('${name}')">Choose media</button></div>`;
const repeatEditor=(label,name,values=[],offer=false)=>`<div class="repeat-wrap"><div class="repeat-label"><span>${label}</span><button class="btn ghost" type="button" onclick="addRepeat('${name}',${offer})">＋ Add</button></div><div class="repeat-list" data-repeat="${name}" data-offer="${offer}">${values.length?values.map((value,index)=>repeatRow(name,value,index,offer)).join(''):'<div class="empty-repeat">Nothing added yet. Use the Add button to create one.</div>'}</div></div>`;
function repeatRow(name,value,index,offer=false){let title=offer?(value.title||''):value,description=offer?(value.description||''):'';return `<div class="repeat-item ${offer?'offer':''}"><span class="drag-handle">⠿</span><input value="${esc(title)}" placeholder="${offer?'Offer title':'Type an item'}">${offer?`<input value="${esc(description)}" placeholder="Short explanation">`:''}<button class="icon-btn" type="button" aria-label="Remove" onclick="this.parentElement.remove()">×</button></div>`}
function addRepeat(name,offer=false){let list=document.querySelector(`[data-repeat="${name}"]`);list.querySelector('.empty-repeat')?.remove();list.insertAdjacentHTML('beforeend',repeatRow(name,'',list.children.length,offer));list.querySelector('input:last-of-type')?.focus()}
async function openMediaPicker(target){let result=await api('/admin/media');let drawer=document.createElement('div');drawer.className='media-drawer';drawer.innerHTML=`<div class="media-panel"><div class="head"><div><p class="ey">MEDIA LIBRARY</p><h2>Choose a file</h2><p class="muted">Select existing media for this content.</p></div><button class="btn ghost" type="button" data-close>Close</button></div><div class="media-grid">${result.items.map(file=>`<button type="button" class="media-choice" data-url="${esc(file.url)}">${file.type.startsWith('image/')?`<img src="${esc(file.url)}" alt="${esc(file.altText)}">`:`<video src="${esc(file.url)}" muted></video>`}<span>${esc(file.name)}</span></button>`).join('')||'<div class="empty-repeat">Your media library is empty.</div>'}</div></div>`;document.body.append(drawer);drawer.querySelector('[data-close]').onclick=()=>drawer.remove();drawer.onclick=e=>{let choice=e.target.closest('[data-url]');if(choice){let field=document.querySelector(`[name="${target}"]`);field.value=choice.dataset.url;field.dispatchEvent(new Event('input',{bubbles:true}));drawer.remove()}else if(e.target===drawer)drawer.remove()}}
function editorPreview(kind,item){return `<aside class="editor-side"><div class="card visual-preview"><div class="preview-media">${item.image||item.thumbnail?`<img id="liveImage" src="${esc(item.image||item.thumbnail)}">`:''}</div><div class="preview-copy"><p class="ey">LIVE PREVIEW</p><h3 id="liveTitle">${esc(item.title||item.question||'Untitled')}</h3><p id="liveDescription">${esc(item.tagline||item.description||item.answer||'Your summary will appear here.')}</p></div></div><div class="card publish-card"><p class="ey">PUBLISHING</p><div class="publish-row"><span>Visibility</span><strong id="visibilityText">${item.status==='hidden'||item.visible===false?'Hidden':'Visible'}</strong></div><div class="publish-row"><span>Changes</span><strong>Publish immediately</strong></div><button class="btn" form="visualEditor">Save & publish</button><button class="btn ghost" type="button" onclick="${kind==='faqs'?'contactManager()':`list('${kind}')`}">Cancel</button></div></aside>`}
function bindPreview(form){let update=()=>{let title=form.querySelector('[name="title"],[name="question"]')?.value||'Untitled';let description=form.querySelector('[name="tagline"],[name="description"],[name="answer"]')?.value||'Your summary will appear here.';let image=form.querySelector('[name="image"],[name="thumbnail"]')?.value;$('#liveTitle').textContent=title;$('#liveDescription').textContent=description;$('#visibilityText').textContent=form.hidden.checked?'Hidden':'Visible';let box=$('#liveImage');if(image){if(!box){box=document.createElement('img');box.id='liveImage';document.querySelector('.preview-media').append(box)}box.src=image}else box?.remove()};form.addEventListener('input',update)}
edit=async function(kind,id){
  let item=id?items.find(x=>x.id===id):{status:'published',visible:true,year:new Date().getFullYear(),deliverables:[],whatWeOffer:[]};let categories=kind==='portfolio'?(await api('/admin/content/categories')).items:[];let sections='';
  if(kind==='services'){sections=editorSection('01','Service identity','The name and headline visitors see first.',input('Service name','title',item.title||'')+input('Menu number','number',item.number||'')+input('Short introduction','tagline',item.tagline||'')+input('Hero eyebrow','heroHeadlineTop',item.heroHeadlineTop||'')+input('Hero heading','heroHeadlineMain',item.heroHeadlineMain||''))+editorSection('02','Story & audience','Explain the value of this service in clear language.',input('Description','description',item.description||'',true)+input('Ideal customer','idealFor',item.idealFor||'',true))+editorSection('03','Featured image','Choose how this service is represented visually.',mediaField('Image','image',item.image||'')+input('Image description','imageAlt',item.imageAlt||''))+editorSection('04','What clients receive','Build scannable lists instead of formatting text manually.',repeatEditor('Deliverables','deliverables',item.deliverables||[])+repeatEditor('What we offer','offers',item.whatWeOffer||[],true));}
  else if(kind==='portfolio'){sections=editorSection('01','Project details','Give the work a clear identity.',input('Project title','title',item.title||'')+input('Client','client',item.client||'')+input('Year','year',item.year||'')+`<label>Category<select name="categoryId">${categories.map(c=>`<option value="${c.id}" ${Number(c.id)===Number(item.categoryId)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`)+editorSection('02','Project story','Describe the challenge, idea and outcome.',input('Description','description',item.description||'',true)+repeatEditor('Deliverables','deliverables',item.deliverables||[]))+editorSection('03','Project media','Choose a thumbnail and the main image or video.',mediaField('Thumbnail','thumbnail',item.thumbnail||'')+mediaField('Main media','mediaUrl',item.mediaUrl||'')+`<label>Media type<select name="mediaType"><option value="image" ${item.mediaType!=='video'?'selected':''}>Image</option><option value="video" ${item.mediaType==='video'?'selected':''}>Video</option></select></label><label class="check"><input type="checkbox" name="isEmbed" ${item.isEmbed?'checked':''}> Use an embedded video link</label>`);}
  else sections=editorSection('01','Question','Write the question exactly as a visitor would ask it.',input('Question','question',item.question||''))+editorSection('02','Answer','Keep the answer clear, useful and easy to scan.',input('Answer','answer',item.answer||'',true));
  $('#view').innerHTML=`<button class="btn ghost editor-back" type="button" onclick="${kind==='faqs'?"contactManager()":`list('${kind}')`}">← Back</button><form id="visualEditor" class="editor-layout"><div class="editor-main">${sections}<section class="card editor-section"><div class="section-head"><span class="section-no">✓</span><div><h2>Visibility</h2><p>Hide this item without deleting it.</p></div></div><label class="check"><input type="checkbox" name="hidden" ${(item.status==='hidden'||item.visible===false)?'checked':''}> Hide from the public website</label>${kind==='portfolio'?`<label class="check"><input type="checkbox" name="featured" ${item.featured?'checked':''}> Feature on the home page</label>`:''}</section></div>${editorPreview(kind,item)}</form>`;
  let form=$('#visualEditor');bindPreview(form);form.onsubmit=async event=>{event.preventDefault();let data=Object.fromEntries(new FormData(form));form.querySelectorAll('[data-repeat]').forEach(list=>{let rows=[...list.querySelectorAll('.repeat-item')];data[list.dataset.repeat]=rows.map(row=>{let fields=row.querySelectorAll('input');return list.dataset.offer==='true'?fields[0].value+' | '+fields[1].value:fields[0].value}).filter(Boolean).join('\n')});data.status=form.hidden.checked?'hidden':'published';data.visible=!form.hidden.checked;data.featured=!!form.featured?.checked;data.isEmbed=!!form.isEmbed?.checked;try{form.classList.add('saving');await api('/admin/content/'+kind+(id?'/'+id:''),{method:id?'PUT':'POST',body:JSON.stringify(data)});toast('Saved — your website is up to date.');kind==='faqs'?contactManager():list(kind)}catch(error){toast(error.message)}finally{form.classList.remove('saving')}};
}
async function pageForm(p){let all=(await api('/admin/settings')).settings,key=p==='settings'?'studio_info':p+'_content',v=all[key]?.value||{},fields='';if(p==='settings')fields=input('Brand name','brandName',v.brandName||'Joozz Designing')+input('Tagline','tagline',v.tagline||'')+input('Founder name','founder',v.founder||'')+input('Experience','experience',v.experience||'')+input('Founder story','founderBio',v.founderBio||'',true)+input('Email address','email',v.email||'')+input('UK phone','phoneUK',v.phoneUK||'')+input('India phone','phoneIndia',v.phoneIndia||'')+input('Registered office','registeredOffice',v.registeredOffice||'',true)+input('UK location','locationUK',v.locationUK||'')+input('India location','locationIndia',v.locationIndia||'')+input('Instagram link','instagram',v.socials?.instagram||'')+input('LinkedIn link','linkedin',v.socials?.linkedin||'')+input('Behance link','behance',v.socials?.behance||'')+input('Dribbble link','dribbble',v.socials?.dribbble||'');else if(p==='home')fields=input('Hero heading','heroHeading',v.heroHeading||'')+input('Hero subheading','heroSubheading',v.heroSubheading||'',true)+input('Call to action text','ctaText',v.ctaText||'')+input('Call to action link','ctaLink',v.ctaLink||'')+input('Hero video link','heroVideo',v.heroVideo||'')+input('Studio introduction','introduction',v.introduction||'',true)+input('Final call to action heading','finalCta',v.finalCta||'');else fields=input('Heading','heading',v.heading||'')+input('Introduction','introduction',v.introduction||'',true)+input('Call to action text','ctaText',v.ctaText||'')+input('Call to action link','ctaLink',v.ctaLink||'');$('#view').innerHTML=`<form id="page" class="card form"><h2>${meta[p][0]}</h2><p class="muted">Write naturally — visitors will see this text.</p><div class="cols">${fields}</div><button class="btn">Save changes</button></form>`;$('#page').onsubmit=async e=>{e.preventDefault();let f=e.target,d=Object.fromEntries(new FormData(f));if(p==='settings'){d.socials={instagram:d.instagram,linkedin:d.linkedin,behance:d.behance,dribbble:d.dribbble};delete d.instagram;delete d.linkedin;delete d.behance;delete d.dribbble}await api('/admin/settings/'+key,{method:'PUT',body:JSON.stringify({value:d})});toast('Saved — changes are now live.')}}
pageForm=async function(page){let all=(await api('/admin/settings')).settings,key=page==='settings'?'studio_info':page+'_content',value=all[key]?.value||{},sections='';if(page==='settings'){sections=editorSection('01','Brand identity','The name and personality used across the website.',input('Brand name','brandName',value.brandName||'Joozz Designing')+input('Tagline','tagline',value.tagline||'')+input('Founder name','founder',value.founder||'')+input('Experience','experience',value.experience||''))+editorSection('02','Founder story','Tell visitors who is behind the studio.',input('Founder story','founderBio',value.founderBio||'',true))+editorSection('03','Contact details','These details appear across contact areas and the footer.',input('Email address','email',value.email||'')+input('UK phone','phoneUK',value.phoneUK||'')+input('India phone','phoneIndia',value.phoneIndia||'')+input('Registered office','registeredOffice',value.registeredOffice||'',true)+input('UK location','locationUK',value.locationUK||'')+input('India location','locationIndia',value.locationIndia||''))+editorSection('04','Social profiles','Paste the public link for each studio profile.',input('Instagram','instagram',value.socials?.instagram||'')+input('LinkedIn','linkedin',value.socials?.linkedin||'')+input('Behance','behance',value.socials?.behance||'')+input('Dribbble','dribbble',value.socials?.dribbble||''));}else if(page==='home'){sections=editorSection('01','Hero message','The first message people see when they visit.',input('Hero heading','heroHeading',value.heroHeading||'')+input('Hero subheading','heroSubheading',value.heroSubheading||'',true))+editorSection('02','Primary action','Guide visitors toward the next step.',input('Button text','ctaText',value.ctaText||'')+input('Button link','ctaLink',value.ctaLink||''))+editorSection('03','Hero media','Choose the motion backdrop for the opening section.',mediaField('Hero video','heroVideo',value.heroVideo||''))+editorSection('04','Supporting story','Introduce the studio and close with a strong invitation.',input('Studio introduction','introduction',value.introduction||'',true)+input('Final call to action','finalCta',value.finalCta||''));}else{sections=editorSection('01','Page introduction','Set the page heading and opening copy.',input('Heading','heading',value.heading||'')+input('Introduction','introduction',value.introduction||'',true))+editorSection('02','Call to action','Choose where visitors should go next.',input('Button text','ctaText',value.ctaText||'')+input('Button link','ctaLink',value.ctaLink||''));}let preview={title:value.heroHeading||value.heading||value.brandName||meta[page][0],description:value.heroSubheading||value.introduction||value.tagline||'Your content preview will update as you type.'};$('#view').innerHTML=`<button class="btn ghost editor-back" type="button" onclick="${page==='contact'?'contactManager()':`nav('${page}')`}">← Back</button><form id="pageVisualEditor" class="editor-layout"><div class="editor-main">${sections}</div><aside class="editor-side"><div class="card visual-preview"><div class="preview-media"></div><div class="preview-copy"><p class="ey">PAGE PREVIEW</p><h3 id="liveTitle">${esc(preview.title)}</h3><p id="liveDescription">${esc(preview.description)}</p></div></div><div class="card publish-card"><p class="ey">PUBLISHING</p><div class="publish-row"><span>Page</span><strong>${esc(meta[page][0])}</strong></div><div class="publish-row"><span>Changes</span><strong>Publish immediately</strong></div><button class="btn" form="pageVisualEditor">Save & publish</button><button class="btn ghost" type="button" onclick="${page==='contact'?'contactManager()':`nav('${page}')`}">Cancel</button></div></aside></form>`;let form=$('#pageVisualEditor');form.addEventListener('input',()=>{$('#liveTitle').textContent=form.querySelector('[name="heroHeading"],[name="heading"],[name="brandName"]')?.value||meta[page][0];$('#liveDescription').textContent=form.querySelector('[name="heroSubheading"],[name="introduction"],[name="tagline"]')?.value||'Your content preview will update as you type.'});form.onsubmit=async event=>{event.preventDefault();let data=Object.fromEntries(new FormData(form));if(page==='settings'){data.socials={instagram:data.instagram,linkedin:data.linkedin,behance:data.behance,dribbble:data.dribbble};delete data.instagram;delete data.linkedin;delete data.behance;delete data.dribbble}try{form.classList.add('saving');await api('/admin/settings/'+key,{method:'PUT',body:JSON.stringify({value:data})});toast('Saved — changes are now live.')}catch(error){toast(error.message)}finally{form.classList.remove('saving')}}}
async function media(){let r=await api('/admin/media');$('#view').innerHTML=`<div class="card"><h2>Upload media</h2><p class="muted">JPG, PNG, WebP, GIF, MP4 or WebM — maximum 25 MB.</p><form id="upload"><input type="file" name="file" accept="image/*,video/mp4,video/webm" required>${input('Image description','altText','')}<button class="btn">Upload file</button></form></div><div class="list" style="margin-top:18px">${r.items.map(x=>`<div class="row"><img class="thumb" src="${esc(x.url)}"><div class="grow"><b>${esc(x.name)}</b><small>${esc(x.type)} · ${Math.ceil(x.size/1024)} KB</small></div><button class="btn ghost" onclick="navigator.clipboard.writeText(location.origin+'${esc(x.url)}');toast('Link copied.')">Copy link</button></div>`).join('')||'<div class="card muted">No media uploaded yet.</div>'}</div>`;$('#upload').onsubmit=async e=>{e.preventDefault();try{await api('/admin/media',{method:'POST',body:new FormData(e.target)});toast('Upload complete.');media()}catch(e){toast(e.message)}}}
async function enquiries(){let r=await api('/admin/enquiries');$('#view').innerHTML='<div class="list">'+(r.items.map(e=>`<div class="row"><div class="grow"><b>${esc(e.name)} — ${esc(e.service)}</b><small>${esc(e.email)} · ${new Date(e.createdAt).toLocaleDateString()}<br>${esc(e.message)}</small></div><select onchange="status(${e.id},this.value)">${['new','read','replied','archived'].map(s=>'<option '+(s===e.status?'selected':'')+'>'+s+'</option>').join('')}</select></div>`).join('')||'<div class="card muted">No enquiries yet.</div>')+'</div>'}async function status(id,s){await api('/admin/enquiries/'+id,{method:'PATCH',body:JSON.stringify({status:s})});toast('Enquiry updated.')}
async function seo(){let [n,p]=await Promise.all([api('/admin/content/navigation'),api('/admin/content/pages')]);items=n.items;window.seoPages=p.items;$('#view').innerHTML=`<div class="card"><div class="head"><div><h2>Website menu</h2><p class="muted">Change labels, links and where they appear.</p></div><button class="btn" onclick="menuForm()">Add menu item</button></div>${n.items.map(x=>`<div class="row"><div class="grow"><b>${esc(x.label)}</b><small>${esc(x.location.replaceAll('_',' '))} · ${esc(x.url)}</small></div><button class="btn ghost" onclick="menuForm(${x.id})">Edit</button><button class="btn ghost danger" onclick="del('navigation',${x.id}).then(seo)">Delete</button></div>`).join('')}</div><div class="card" style="margin-top:18px"><h2>Search appearance</h2><p class="muted">Control the title and summary shown in search results.</p>${p.items.map(x=>`<div class="row"><div class="grow"><b>${esc(x.title)}</b><small>${esc(x.metaTitle||'No search title set')}</small></div><button class="btn ghost" onclick="pageSeoForm(${x.id})">Edit</button></div>`).join('')}</div>`}
function menuForm(id){let i=id?items.find(x=>x.id===id):{location:'header',visible:true};$('#view').innerHTML=`<form class="card form" id="menuForm"><h2>${id?'Edit':'Add'} menu item</h2>${input('Menu label','label',i.label||'')}${input('Link','url',i.url||'/')}<label>Menu area<select name="location"><option value="header" ${i.location==='header'?'selected':''}>Main menu</option><option value="footer_studio" ${i.location==='footer_studio'?'selected':''}>Footer — Studio</option><option value="footer_disciplines" ${i.location==='footer_disciplines'?'selected':''}>Footer — Disciplines</option></select></label>${input('Position','sortOrder',i.sortOrder||0)}<label class="check"><input type="checkbox" name="visible" ${i.visible!==false?'checked':''}> Visible</label><button class="btn">Save menu</button></form>`;$('#menuForm').onsubmit=async e=>{e.preventDefault();let f=e.target,d=Object.fromEntries(new FormData(f));d.visible=f.visible.checked;await api('/admin/content/navigation'+(id?'/'+id:''),{method:id?'PUT':'POST',body:JSON.stringify(d)});toast('Menu saved.');seo()}}
function pageSeoForm(id){let i=window.seoPages.find(x=>x.id===id);$('#view').innerHTML=`<form class="card form" id="pageSeo"><h2>${esc(i.title)} search appearance</h2>${input('Page name','title',i.title)}${input('Search title','metaTitle',i.metaTitle||'')}${input('Search description','metaDescription',i.metaDescription||'',true)}<label class="check"><input type="checkbox" name="indexable" ${i.indexable!==false?'checked':''}> Allow search engines to show this page</label><button class="btn">Save search settings</button></form>`;$('#pageSeo').onsubmit=async e=>{e.preventDefault();let f=e.target,d=Object.fromEntries(new FormData(f));d.indexable=f.indexable.checked;await api('/admin/content/pages/'+id,{method:'PUT',body:JSON.stringify(d)});toast('Search settings saved.');seo()}}
$('#loginForm').onsubmit=async e=>{e.preventDefault();try{let r=await api('/admin/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});csrf=r.csrfToken;$('#login').classList.add('hide');$('#app').classList.remove('hide');render()}catch(e){$('#err').textContent=e.message}};$('#logout').onclick=async()=>{await api('/admin/auth/logout',{method:'POST'});location.reload()};api('/admin/auth/me').then(r=>{csrf=r.csrfToken;$('#login').classList.add('hide');$('#app').classList.remove('hide');render()}).catch(()=>{});
</script></body></html>
